 "content": "from collections import Counter


def transform(grid):
    """Repair isolated one-cell intrusions by matching their surrounding pattern."""
    h, w = len(grid), len(grid[0])
    src = [row[:] for row in grid]
    out = [row[:] for row in grid]
    dirs = ((-1, 0), (1, 0), (0, -1), (0, 1))

    # A corrupted pixel is a singleton in its own color under 4-connectivity.
    for r in range(h):
        for c in range(w):
            color = src[r][c]
            if any(0 <= r + dr < h and 0 <= c + dc < w and
                   src[r + dr][c + dc] == color for dr, dc in dirs):
                continue
            around = [src[r + dr][c + dc] for dr, dc in dirs
                      if 0 <= r + dr < h and 0 <= c + dc < w]
            if not around:
                continue
            counts = Counter(around)
            best = max(counts.values())
            candidates = [v for v, n in counts.items() if n == best]
            if len(candidates) == 1:
                out[r][c] = candidates[0]
                continue

            # Resolve a local tie using the broader neighborhood, then nearest
            # matching pattern along the row/column; deterministic final tie.
            broad = []
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
                    if (dr or dc) and 0 <= rr < h and 0 <= cc < w:
                        broad.append(src[rr][cc])
            bcounts = Counter(v for v in broad if v in candidates)
            bbest = max((bcounts.get(v, 0) for v in candidates), default=0)
            winners = [v for v in candidates if bcounts.get(v, 0) == bbest]
            if len(winners) == 1:
                out[r][c] = winners[0]
            else:
                distances = {}
                for v in winners:
                    d = h + w
                    for rr in range(h):
                        for cc in range(w):
                            if src[rr][cc] == v:
                                d = min(d, abs(rr-r) + abs(cc-c))
                    distances[v] = d
                out[r][c] = min(winners, key=lambda v: (distances[v], v))
    return out
